public static class AuthorDataLoaders
{
    [DataLoader]
    public static async Task<IReadOnlyDictionary<int, Author>> GetAuthorByIdAsync(
        IReadOnlyList<int> ids, AppDbContext db, CancellationToken ct)
        => await db.Authors.Where(a => ids.Contains(a.Id))
                           .ToDictionaryAsync(a => a.Id, ct);
}

// resolver pola Book.author
public static Task<Author?> GetAuthorAsync(
    [Parent] Book book, IAuthorByIdDataLoader authorById, CancellationToken ct)
    => authorById.LoadAsync(book.AuthorId, ct);

